import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Store } from '../src/core/store.js';
import type { Memory, Source } from '../src/types.js';

/** Synthetic local fixtures only. The vectors below are deliberately hand-authored,
 * not generated by or representative of any real embedding model. */
const MOCK_ROUTE = 'synthetic-hand-authored-vectors';
const DAY = 86_400_000;

test('synthetic recall assessment versus the former latest-40 memory context', t => {
  const root=mkdtempSync(join(tmpdir(),'keep-whale-recall-benchmark-'));
  let time=Date.UTC(2026,7,1,10);
  const store=new Store(root,()=>time);
  try {
    function add(id:string, text:string, options:{ kind?:'user_fact'|'shared_episode'; validFrom?:number } = {}):Memory {
      const kind=options.kind??'user_fact';
      const source:Source={id:'source-'+id,kind,text,occasion:'event-'+id,createdAt:time,processed:false,revoked:false,provenance:kind==='shared_episode'?'exchange':'user_statement'};
      assert.equal(store.addSource(source),true);
      const memory=store.saveMemory({kind,text,sourceIds:[source.id],evidence:[{sourceId:source.id,quote:text}],validFrom:options.validFrom});
      assert.ok(memory);time+=60_000;return memory;
    }
    const event=add('old-event','去年夏天我们一起在西湖看过晚霞',{kind:'shared_episode'});
    const feline=add('feline','用户喜欢养猫');
    const namePet=add('same-name-pet','阿青是我的宠物猫');
    const nameWork=add('same-name-work','阿青是我的同事，在北京工作');
    const positive=add('positive','我喜欢香菜');
    const negative=add('negative','我不喜欢香菜');
    assert.ok(store.linkMemories({fromId:negative.id,toId:positive.id,kind:'contradicts',evidence:[{sourceId:'source-negative',quote:'我不喜欢香菜'}]}));
    const oldTime=time;
    const oldPreference=add('old-preference','以前我喜欢喝红茶',{validFrom:oldTime});
    time+=60*DAY;
    const changedTime=time;
    const newPreference=add('new-preference','现在我喜欢喝绿茶',{validFrom:changedTime});
    assert.ok(store.linkMemories({fromId:newPreference.id,toId:oldPreference.id,kind:'updates',evidence:[{sourceId:'source-new-preference',quote:'现在我喜欢喝绿茶'}]}));
    // More than 40 later, unrelated episodes ensure a recency-only baseline loses
    // every target. Unique English IDs avoid accidental Chinese overlap.
    for(let i=0;i<60;i++) add('noise-'+i,`用户保存编号 N${i} 的资料`);
    const mockRevision=store.revision();
    assert.equal(store.saveVector(feline.id,feline.version??1,MOCK_ROUTE,[1,0,0],mockRevision),true);
    assert.equal(store.saveVector(namePet.id,namePet.version??1,MOCK_ROUTE,[0,1,0],mockRevision),true);
    assert.equal(store.saveVector(nameWork.id,nameWork.version??1,MOCK_ROUTE,[0,0,1],mockRevision),true);
    const baseline=store.memories().slice(0,40).map(m=>m.id);
    const checks=[
      {label:'久远共同经历',query:'那次西湖晚霞发生了什么',gold:[event],role:'shared_episode' as const},
      {label:'中文近义（手工模拟向量）',query:'我对喵星人有什么感受',gold:[feline],role:'user_fact' as const,vector:[1,0,0]},
      {label:'同名对象：同事',query:'阿青同事在哪里工作',gold:[nameWork],role:'user_fact' as const},
      {label:'同名对象：宠物',query:'阿青宠物是什么',gold:[namePet],role:'user_fact' as const},
      {label:'否定偏好',query:'我不喜欢香菜吗',gold:[negative],role:'user_fact' as const},
      {label:'当前更新',query:'现在喜欢绿茶吗',gold:[newPreference],role:'user_fact' as const},
      {label:'时间更新历史',query:'以前喜欢什么茶',gold:[oldPreference,newPreference],role:'user_fact' as const},
    ];
    let newAny=0,newAll=0,baselineAny=0,baselineAll=0;
    const failures:string[]=[];
    for(const check of checks) {
      const opts=check.vector?{vector:check.vector,routeKey:MOCK_ROUTE,limit:5}:{limit:5};
      const result=store.recall(check.query,opts),ids=result.hits.map(hit=>hit.memory.id),gold=check.gold.map(m=>m.id);
      const any=gold.some(id=>ids.includes(id)),all=gold.every(id=>ids.includes(id));
      if(any)newAny++;if(all)newAll++;if(gold.some(id=>baseline.includes(id)))baselineAny++;if(gold.every(id=>baseline.includes(id)))baselineAll++;
      if(!all)failures.push(`${check.label}: expected ${gold.join(',')} within top-5, got ${ids.join(',')}`);
      for(const match of check.gold.filter(m=>ids.includes(m.id))) {
        const detail=store.memoryDetail(match.id);
        assert.ok(detail,`${check.label} must have memory detail`);
        assert.equal(detail.memory.kind,check.role);
        assert.ok(detail.sources.some(s=>s.id===match.sourceIds[0] && s.kind===check.role && s.text===match.text && s.createdAt===match.createdAt),`${check.label}: source, speaker role and timestamp must agree`);
        assert.ok(detail.memory.evidence?.every(e=>detail.sources.some(s=>s.id===e.sourceId&&s.text.slice(e.start,e.end)===e.quote)),`${check.label}: quotes must trace to source spans`);
      }
      if(check.label==='中文近义（手工模拟向量）')assert.equal(result.mode,'hybrid');
      if(check.label==='同名对象：同事' && ids.includes(nameWork.id) && ids.includes(namePet.id) && ids.indexOf(nameWork.id)>ids.indexOf(namePet.id)) failures.push('同名对象：同事排序落后于宠物');
      if(check.label==='同名对象：宠物' && ids.includes(nameWork.id) && ids.includes(namePet.id) && ids.indexOf(namePet.id)>ids.indexOf(nameWork.id)) failures.push('同名对象：宠物排序落后于同事');
      if(check.label==='否定偏好' && ids.includes(positive.id) && ids.includes(negative.id) && ids.indexOf(negative.id)>ids.indexOf(positive.id)) failures.push('否定偏好：错误的肯定事实排在否定事实前面');
      if(check.label==='当前更新' && ids.includes(oldPreference.id)) failures.push('当前更新：已过时的旧偏好出现在当前召回');
    }
    const conflicting=store.memoryDetail(negative.id)!;
    assert.equal(conflicting.memory.status,'uncertain');
    assert.ok(conflicting.sources.some(s=>s.id==='source-negative'&&s.text==='我不喜欢香菜'));
    assert.ok(conflicting.relations.some(r=>r.kind==='contradicts'&&r.toId===positive.id&&r.evidence.some(e=>e.sourceId==='source-negative'&&e.quote==='我不喜欢香菜')));
    assert.ok(store.memoryDetail(positive.id)!.sources.some(s=>s.id==='source-positive'&&s.text==='我喜欢香菜'));
    const oldDetail=store.memoryDetail(oldPreference.id)!;
    assert.equal(oldDetail.memory.status,'superseded');assert.equal(oldDetail.memory.validFrom,oldTime);assert.equal(oldDetail.memory.validTo,changedTime);
    const relation=oldDetail.relations.find(r=>r.kind==='updates' && r.fromId===newPreference.id && r.toId===oldPreference.id);
    assert.ok(relation?.evidence.some(e=>e.sourceId==='source-new-preference'&&e.quote==='现在我喜欢喝绿茶'));
    const noAnswer=store.recall('鳄梨宇宙飞船',{limit:5});
    if(noAnswer.hits.length)failures.push('无答案：无依据提问仍召回了无关候选，不能将其视为有依据回答');
    t.diagnostic(`合成场景 ${checks.length} 项；Recall@5 任一证据：新 ${newAny}/${checks.length}，最近40 ${baselineAny}/${checks.length}；完整证据：新 ${newAll}/${checks.length}，最近40 ${baselineAll}/${checks.length}；无答案候选数 ${noAnswer.hits.length}。近义向量为手工模拟，未测试真实语义模型或回答生成。`);
    assert.deepEqual(failures,[]);
  } finally {store.close();rmSync(root,{recursive:true,force:true});}
});
